let cleanText = text.replace(/```json/gi, '').replace(/```/g, '').trim();
const start = cleanText.indexOf('[');
const end = cleanText.lastIndexOf(']');
if (start !== -1 && end !== -1) {
    cleanText = cleanText.substring(start, end + 1);
} else {
    const startObj = cleanText.indexOf('{');
    const endObj = cleanText.lastIndexOf('}');
    if (startObj !== -1 && endObj !== -1) {
        cleanText = '[' + cleanText.substring(startObj, endObj + 1) + ']';
    }
}
cleanText = cleanText.replace(/,\s*([}\]])/g, "$1");
try {
  let plan = JSON.parse(cleanText);
  if (!Array.isArray(plan)) {
    if (typeof plan === 'object' && plan !== null && plan.action) {
      plan = [plan];
    } else {
      throw new Error("Parsed JSON is not an array and doesn't look like an action object.");
    }
  }

// v5.2: 'Error Fixer Switch' has no fallbackOutput, so an item whose action it
// does not recognise is discarded with no error and no log. Validate here, where
// it can be reported, rather than losing it there.
const VALID = ['ReplaceFileContent', 'ExecuteCommand', 'WriteFile'];
const bad = [];
plan = plan.filter((item) => {
  if (!item || VALID.indexOf(item.action) === -1) { bad.push(JSON.stringify(item).slice(0, 120)); return false; }
  if (item.action === 'ReplaceFileContent' && (typeof item.targetContent !== 'string' || !item.targetContent.length)) {
    bad.push('ReplaceFileContent with empty targetContent for ' + (item.filePath || '?')); return false;
  }
  return true;
});
if (bad.length) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:5153/api/migrationjob/' + ($('Execute Webhook').first().json.body.job_id) + '/logs',
      body: { level: 'warning', phase: 'Execute',
              message: 'Error Fixer produced ' + bad.length + ' unusable step(s); they were dropped.',
              details: bad.join('\n') },
      json: true
    });
  } catch (e) {}
}

  return plan.map(item => ({ json: item }));
} catch (e) {
  throw new Error("LLM did not output valid JSON array:\n" + cleanText + "\nError: " + e.message);
}

